package com.e9rental;
import com.e9rental.config.*;
import com.e9rental.connector.*;
import com.e9rental.model.*;
import com.e9rental.service.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.assertj.core.api.Assertions.*;
class WhatsAppMetadataTest {
    @TempDir Path temp;WhatsAppPolicy policy=WhatsAppFixtures.policy();WhatsAppMessageStore store;WhatsAppMetadataService service;
    @BeforeEach void setup(){store=new WhatsAppMessageStore("jdbc:h2:file:"+temp.resolve("messages").toString().replace('\\','/'),Fixtures.JSON);service=new WhatsAppMetadataService(policy,store,WhatsAppFixtures.CLOCK,Fixtures.JSON);}
    static ObjectNode metadata(String group,long version){var e=Fixtures.JSON.createObjectNode();e.put("data_mode","SIMULATED");e.put("group_id",group);e.put("group_name","Synthetic Site team");e.put("version",version);e.put("updated_at","2026-10-16T12:00:00Z");var p=e.putArray("participants").addObject();p.put("sender_id","sim-user-test");p.put("display_name","Synthetic Operator");p.put("number","sim-number-001");return e;}
    WhatsAppOutput snapshot(){return new WhatsAppExportService(policy,store,new WhatsAppSummaryService(),Fixtures.JSON,WhatsAppFixtures.CLOCK,temp.resolve("output.json").toString()).snapshot();}
    @Test void metadataVersionsUpdateRosterWithoutChangingMessageIdentityAndSurviveRestart(){
        var event=WhatsAppFixtures.event("sim-message","sim-group-rentals","I will deliver on 2026-10-20.");new WhatsAppIngestionService(policy,store,WhatsAppFixtures.CLOCK).ingest(event);var first=snapshot().messages().getFirst();var m=metadata("sim-group-rentals",1);assertThat(service.ingest(m).status()).isEqualTo("ACCEPTED");assertThat(service.ingest(m).status()).isEqualTo("DUPLICATE");
        var update=metadata("sim-group-rentals",2);update.put("group_name","Synthetic Updated Site team");((ObjectNode)update.path("participants").get(0)).put("display_name","Synthetic Updated Operator");assertThat(service.ingest(update).status()).isEqualTo("ACCEPTED");assertThat(service.ingest(m).status()).isEqualTo("CONFLICT");var conflicting=update.deepCopy();conflicting.put("group_name","Another synthetic name");assertThat(service.ingest(conflicting).status()).isEqualTo("CONFLICT");
        store=new WhatsAppMessageStore("jdbc:h2:file:"+temp.resolve("messages").toString().replace('\\','/'),Fixtures.JSON);var out=snapshot();var message=out.messages().getFirst();assertThat(message.source().documentId()).isEqualTo(first.source().documentId());assertThat(message.source().sourceVersion()).isEqualTo(first.source().sourceVersion());assertThat(message.source().contentHash()).isEqualTo(first.source().contentHash());assertThat(message.source().metadata().get("current_sender_display_name")).isEqualTo("Synthetic Updated Operator");assertThat(out.groups().getFirst().groupName()).isEqualTo("Synthetic Updated Site team");
    }
    @Test void excludedMetadataIsRejectedBeforeRosterValidationAndNeverSaved(){var m=metadata("sim-group-excluded",1);m.put("group_name","M4_EXCLUDED_METADATA_CANARY");m.set("participants",Fixtures.JSON.createObjectNode().put("malformed","M4_EXCLUDED_METADATA_CANARY"));assertThat(service.ingest(m).status()).isEqualTo("REJECTED");assertThat(store.selectedMetadata(policy.tenant(),policy.account(),Set.of("sim-group-excluded"))).isEmpty();assertThat(snapshot().groups()).noneSatisfy(g->assertThat(g.groupName()).isEqualTo("M4_EXCLUDED_METADATA_CANARY"));}
    @Test void malformedAndRealLookingContactMetadataAreRejected(){
        for(String field:List.of("version","updated_at","participants","data_mode")){var e=metadata("sim-group-rentals",1);e.remove(field);assertThat(service.ingest(e).status()).isEqualTo("INVALID");}
        for(String bad:List.of("bad-time","2999-01-01T00:00:00Z")){var e=metadata("sim-group-rentals",1);e.put("updated_at",bad);assertThat(service.ingest(e).status()).isEqualTo("INVALID");}
        var e=metadata("sim-group-rentals",1);((ObjectNode)e.path("participants").get(0)).put("number","+10000000000");assertThat(service.ingest(e).status()).isEqualTo("INVALID");e=metadata("sim-group-rentals",1);((ArrayNode)e.path("participants")).add(e.path("participants").get(0).deepCopy());assertThat(service.ingest(e).status()).isEqualTo("INVALID");assertThat(store.selectedMetadata(policy.tenant(),policy.account(),policy.selectedGroups())).isEmpty();
    }
    @Test void missingNamesAndNumbersStayUnknownAndRemovedRosterDoesNotEraseMessages(){var intake=new WhatsAppIngestionService(policy,store,WhatsAppFixtures.CLOCK);intake.ingest(WhatsAppFixtures.event("sim-one","sim-group-rentals","Please inspect equipment."));var m=metadata("sim-group-rentals",1);m.putNull("group_name");m.set("participants",Fixtures.JSON.createArrayNode());assertThat(service.ingest(m).status()).isEqualTo("ACCEPTED");var g=snapshot().groups().getFirst();assertThat(g.groupName()).isNull();assertThat(g.participants()).singleElement().satisfies(p->{assertThat(p.senderId()).isEqualTo("sim-user-test");assertThat(p.displayName()).isNull();assertThat(p.number()).isNull();});}
    @Test void fileAllowlistOverridesEnvironmentAndFailsClosed()throws Exception{Path path=temp.resolve("groups.json");Files.writeString(path,"{\"selected_groups\":[\"sim-group-rentals\"]}");var p=new WhatsAppPolicy("SIMULATED","sim-group-operations","test-tenant","sim-account-test",path.toString());assertThat(p.selectedGroups()).containsExactly("sim-group-rentals");Files.writeString(path,"{\"selected_groups\":[]}");assertThat(new WhatsAppPolicy("SIMULATED","sim-group-operations","test-tenant","sim-account-test",path.toString()).selectedGroups()).isEmpty();for(String text:List.of("{}","{\"selected_groups\":[\"sim-a\",\"sim-a\"]}","{\"selected_groups\":[123]}","{\"selected_groups\":[],\"selected_groups\":[]}")){Files.writeString(path,text);assertThatThrownBy(()->new WhatsAppPolicy("SIMULATED","sim-group-operations","test-tenant","sim-account-test",path.toString())).isInstanceOf(IllegalArgumentException.class);}}
    @Test void revokedMetadataDoesNotEnterExportIndexOrAnswers(){service.ingest(metadata("sim-group-rentals",1));var revoked=new WhatsAppPolicy("SIMULATED","sim-group-operations",policy.tenant(),policy.account());var output=new WhatsAppExportService(revoked,store,new WhatsAppSummaryService(),Fixtures.JSON,WhatsAppFixtures.CLOCK,"unused").snapshot();assertThat(output.groups()).noneMatch(g->"Synthetic Site team".equals(g.groupName()));assertThat(output.messages()).isEmpty();}
    @Test void interpretationsQuoteExactParticipantMessageSpansWithoutInventedAssignees(){
        var intake=new WhatsAppIngestionService(policy,store,WhatsAppFixtures.CLOCK);for(var entry:Map.of("sim-request","Could you send a quotation?","sim-commit","I will inspect equipment on 2026-10-20.","sim-action","Action: please prepare the checklist.","sim-decision","Decision D1: We agreed to deliver Monday.","sim-negated","I will not deliver. This is a proposal.").entrySet())intake.ingest(WhatsAppFixtures.event(entry.getKey(),"sim-group-rentals",entry.getValue()));
        var out=snapshot();var g=out.groups().getFirst();assertThat(g.summary()).hasSize(3);assertThat(g.requests()).isNotEmpty();assertThat(g.decisions()).singleElement().satisfies(d->assertThat(d.status()).isEqualTo("RECORDED_AGREEMENT"));assertThat(g.commitments()).noneMatch(e->e.text().contains("not deliver"));
        for(var p:g.participantInterpretations())for(var list:List.of(p.requests(),p.commitments(),p.actionItems(),p.decisions()))for(var f:list){var m=out.messages().stream().filter(x->x.source().externalId().equals(f.supportingMessageIds().getFirst())).findFirst().orElseThrow();assertThat(m.source().contentText().substring(f.startOffset(),f.endOffset())).isEqualTo(f.text());assertThat(f.senderId()).isEqualTo(m.source().metadata().get("sender_id"));if(f.kind().equals("ACTION")){assertThat(f.assigneeId()).isNull();assertThat(f.status()).isEqualTo("REQUESTED");}}
    }
    @Test void conflictingDecisionStatementsAreFlaggedNotPresentedAsFinal(){var intake=new WhatsAppIngestionService(policy,store,WhatsAppFixtures.CLOCK);intake.ingest(WhatsAppFixtures.event("sim-a","sim-group-rentals","Decision D1: We agreed to deliver Monday."));intake.ingest(WhatsAppFixtures.event("sim-b","sim-group-rentals","Decision D1: We agreed to deliver Tuesday."));assertThat(snapshot().groups().getFirst().decisions()).hasSize(2).allSatisfy(d->assertThat(d.status()).isEqualTo("CONFLICTING"));}
    @Test void aMentionedDateIsNotInventedAsAnActionDeadline(){var intake=new WhatsAppIngestionService(policy,store,WhatsAppFixtures.CLOCK);intake.ingest(WhatsAppFixtures.event("sim-not-due","sim-group-rentals","Please review the invoice dated 2026-10-01."));intake.ingest(WhatsAppFixtures.event("sim-explicit-due","sim-group-rentals","Action: please prepare the checklist by 2026-10-20."));var group=snapshot().groups().getFirst();for(var participant:group.participantInterpretations())for(var action:participant.actionItems()){if(action.supportingMessageIds().contains("sim-not-due"))assertThat(action.dueDate()).isNull();if(action.supportingMessageIds().contains("sim-explicit-due"))assertThat(action.dueDate()).isEqualTo("2026-10-20");}}

}
